use crate::cpfsk::discrete_integral::DiscreteIntegral;

pub trait IteratorExt: Iterator {
    /// Return an iterator adaptor that integrates over a bitstream to produce an accumulating
    /// sum over the source iterator. The source iterator is assumed to be a discrete binary signal
    /// transformed to a non-return-to-zero (NRZ) space.
    /// Each bit (source iterator item) is interpolated smoothly onto `samples_per_bit` successive
    /// samples (output iterator items) as `f(x)`.
    /// sample. Each iteration advances the upper sum bound `N` by one, adding another term of
    /// `(f(x_prev) + f(x)) / 2`. We assume `Δx=1`.
    ///
    /// The above explanation refers to the trapezoidal rule for discrete integrals:
    ///
    /// ![Trapezoidal Rule](data:image/svg+xml;base64,)
    fn discrete_integral(self, samples_per_bit: usize) -> DiscreteIntegral<Self>
    where
        Self: Sized + Iterator<Item = i8>,
    {
        DiscreteIntegral::new(samples_per_bit, self)
    }
}

impl<I: Iterator> IteratorExt for I {}
